const kFallbackTitle: Record<string, string> = {
  en: 'Your garden needs attention',
  sl: 'Tvoj vrt te čaka',
  de: 'Dein Garten braucht Aufmerksamkeit',
};

// Every push carries this body. See the header for why it is not
// the suggestion body (P10.2).
const kFallbackBody: Record<string, string> = {
  en: 'Tap to see today\'s suggestion',
  sl: 'Tapni za predlog dneva',
  de: 'Tippe für den heutigen Vorschlag',
};

function norm(lang: string | null | undefined): string {
  return lang === 'sl' || lang === 'de' ? lang : 'en';
}

export function pushTitle(messageKey: string, lang: string | null | undefined): string {
  const l = norm(lang);
  return kTitles[l][messageKey] ?? kFallbackTitle[l];
}

export function pushBody(lang: string | null | undefined): string {
  return kFallbackBody[norm(lang)];
}

/** Every message_key with a title here, so a test can sweep all of them
 * through the marker filling instead of naming a lucky few. */
export const kPushMessageKeys: readonly string[] = Object.keys(kTitles.en);
